import java.util.Scanner;
public class JAdjacentConsecutives {
	public static void main(String[] args) {
		//Paso 1: Leer el primer entero que ingresa el usuario
		System.out.println("Ingrese los enteros separados por espacios o salto de linea (ingrese -1 para terminar): ");
		Scanner scan = new Scanner(System.in); 
		int num = scan.nextInt();
		//Paso 2: Leer el resto de los enteros que ingresa el usuario y verificar numeros consecutivos adyacentes
		while (num != -1) {
			int previous = num;
			num = scan.nextInt();
			if ( num != -1 && num - previous == 1 ) {
				System.out.println(previous + " " +num + " are consecutive."); 
			}
		}
		scan.close();
	}
}

